#include <stdio.h>
int main(void) {
  int positive = 0;
  int sum = 0;
  for (int i = 0; i < 5; i++) {
    int value;
    if (scanf("%d", &value) != 1) return 1;
    if (value > 0) {
      positive++;
      sum += value;
    }
  }
  printf("positive=%d,sum=%d\n", positive, sum);
  return 0;
}

