#include <stdio.h>
int main(void) {
  int n;
  if (scanf("%d", &n) != 1 || n < 0 || n > 8) return 1;
  int pass = 0, sum = 0;
  for (int i = 0; i < n; i++) {
    int score;
    if (scanf("%d", &score) != 1) return 1;
    sum += score;
    if (score >= 60) pass++;
  }
  printf("pass=%d,sum=%d\n", pass, sum);
  return 0;
}

