#include <stdio.h>
int main(void) {
  int n;
  if (scanf("%d", &n) != 1 || n < 1 || n > 8) return 1;
  int value;
  if (scanf("%d", &value) != 1) return 1;
  int min = value, max = value, even = value % 2 == 0;
  for (int i = 1; i < n; i++) {
    if (scanf("%d", &value) != 1) return 1;
    if (value < min) min = value;
    if (value > max) max = value;
    if (value % 2 == 0) even++;
  }
  printf("min=%d,max=%d,even=%d\n", min, max, even);
  return 0;
}
